                        seen.add((ny, nx))
                        stack.append((ny, nx))
            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            objects.append({
                'color': color, 'cells': cells,
                'y0': min(ys), 'y1': max(ys),
                'x0': min(xs), 'x1': max(xs),
                'height': max(ys) - min(ys) + 1,
                'width': max(xs) - min(xs) + 1,
                'area': (max(ys) - min(ys) + 1) * (max(xs) - min(xs) + 1)
            })
    frames = [o for o in objects if o['height'] >= 3 and o['width'] >= 4]
    target = min(frames, key=lambda o: (o['area'], o['y0'], o['x0']))
    th, tw = target['height'], target['width']
    out = [[bg] * tw for _ in range(th)]
    for y, x in target['cells']:
        out[y - target['y0']][x - target['x0']] = target['color']

    frame_ids = {id(o) for o in frames}
    markers = {}
    for o in objects:
        if id(o) not in frame_ids:
