                    out[yy][xx] = color

    for color, parts in markers.items():
        horizontal = all(p['height'] == 1 and p['width'] >= 2 for p in parts)
        if horizontal and len(parts) >= 2:
            paint_sides(color, [0, th - 1])
        elif horizontal:
            paint_sides(color, [th - 1])
        elif len(parts) == 1 and parts[0]['height'] == 2 and parts[0]['width'] == 2:
            paint_sides(color, range(min(2, th)))
        else:
